import threading

class Debouncer:
    def __init__(self, delay):
        self.delay = delay
        self.timer = None

    def call(self, fn):
        if self.timer is not None:
            self.timer.cancel()
        self.timer = threading.Timer(self.delay, fn)
        self.timer.start()
